constexpr double kPi = 3.14159265358979323846;
constexpr double kDeg2Rad = kPi / 180.0;
constexpr double kRad2As = 180.0 * 3600.0 / kPi;
constexpr double kAuKm = 149597870.7;
constexpr double kJ2000 = 2451545.0;

double norm3(const double v[3]) {
    return std::sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]);
}

double angle_as(const double a[3], const double b[3]) {
    const double c[3] = {a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2],
                         a[0] * b[1] - a[1] * b[0]};
    const double d = a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
    return std::atan2(norm3(c), d) * kRad2As;
}

// Great-circle separation of two (lon, lat) pairs in degrees, arcsec.
double sep_as(double lon1, double lat1, double lon2, double lat2) {
    const double a[3] = {std::cos(lat1 * kDeg2Rad) * std::cos(lon1 * kDeg2Rad),
                         std::cos(lat1 * kDeg2Rad) * std::sin(lon1 * kDeg2Rad),
                         std::sin(lat1 * kDeg2Rad)};
    const double b[3] = {std::cos(lat2 * kDeg2Rad) * std::cos(lon2 * kDeg2Rad),
                         std::cos(lat2 * kDeg2Rad) * std::sin(lon2 * kDeg2Rad),
                         std::sin(lat2 * kDeg2Rad)};
    return angle_as(a, b);
}

double wrap180(double d) {
    while (d > 180.0)
        d -= 360.0;
    while (d <= -180.0)
        d += 360.0;
    return d;
}

double wrap360(double d) {
    while (d < 0.0)
        d += 360.0;
    while (d >= 360.0)
        d -= 360.0;
    return d;
}

